// ─── File: OAuthRolesDemo.java ───
package com.bank.oauth;

import java.util.*;
import java.util.logging.*;

public class OAuthRolesDemo {
    private static final Logger log = Logger.getLogger(OAuthRolesDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Role 1: Resource Owner
        ResourceOwner rajesh = new ResourceOwner("rajesh", "SAV2001");
        // Role 2: Client (third-party budgeting app)
        Client budgetApp = new Client("budgetapp", "secret");
        // Role 3: Authorization Server
        AuthorizationServer authServer = new AuthorizationServer();
        // Role 4: Resource Server
        ResourceServer resourceServer = new ResourceServer();

        // Owner consents to a LIMITED scope (read only) — no password shared with the app.
        AccessToken token = authServer.authorize(rajesh, budgetApp, Set.of("transactions:read"));
        log.info(() -> "Auth server issued scoped token: " + token.scopes);

        // Client uses the token to READ transactions -> allowed.
        String txns = resourceServer.getTransactions(token, rajesh.accountId);
        log.info(() -> "Resource server returned: " + txns);

        // Same token tries to TRANSFER money -> refused (scope not granted).
        try {
            resourceServer.transfer(token, rajesh.accountId, "CUR3001", 50000);
        } catch (InsufficientScopeException e) {
            log.severe("Transfer refused: " + e.getMessage());
        }
    }
}

// ─── Would be in ResourceOwner.java ───
class ResourceOwner {
    final String username; final String accountId;
    ResourceOwner(String u, String a) { username = u; accountId = a; }
}

// ─── Would be in Client.java ───
class Client {
    final String clientId; final String clientSecret;
    Client(String id, String secret) { clientId = id; clientSecret = secret; }
}

// ─── Would be in AccessToken.java ───
class AccessToken {
    final String subject; final String clientId; final Set<String> scopes;
    AccessToken(String subject, String clientId, Set<String> scopes) {
            this.subject = subject;
            this.clientId = clientId
            this.scopes = scopes;
    }
}

// ─── Would be in InsufficientScopeException.java ───
class InsufficientScopeException extends RuntimeException {
    InsufficientScopeException(String m) { super(m); }
}

// ─── Would be in AuthorizationServer.java ───
class AuthorizationServer {
    AccessToken authorize(ResourceOwner owner, Client client, Set<String> requestedScopes) {
        // Owner authenticated HERE (bank's own login), then consents. App never sees the password.
        return new AccessToken(owner.username, client.clientId, requestedScopes);
    }
}

// ─── Would be in ResourceServer.java ───
class ResourceServer {
    String getTransactions(AccessToken token, String accountId) {
        requireScope(token, "transactions:read");
        return "[2026-10-01 -5000 groceries, 2026-10-05 -2000 fuel]";
    }
    void transfer(AccessToken token, String from, String to, long amount) {
        requireScope(token, "transactions:write"); // not granted -> fails
    }
    private void requireScope(AccessToken token, String scope) {
        if (!token.scopes.contains(scope))
            throw new InsufficientScopeException("token lacks scope: " + scope);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
